  1018→        const det = J.J11 * J.J22 - J.J12 * J.J21;
  1019→        
  1020→        if (Math.abs(det) < 1e-12) {
  1021→            log('Jacobian特異! 計算停止', 'error');
  1022→            return { error: Infinity, converged: false };
  1023→        }
  1024→        
  1025→        let dDelta = (J.J22 * m.deltaP - J.J12 * m.deltaQ) / det;
  1026→        let dV = (-J.J21 * m.deltaP + J.J11 * m.deltaQ) / det;
